// Keep the profile whose current company looks like the agency; otherwise the first result whose name matches; otherwise nothing.
// Name match: surname exact, first name by 3-letter prefix (Benjamin/Ben, Nicholas/Nick, Christopher/Chris).
const a = $('Load agencies').item.json;
let rows = [];
try { const p = JSON.parse(String($json.body || '[]')); rows = Array.isArray(p) ? p : (p.items || []); } catch (e) { rows = []; }
const norm = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llp|group|uk|recruitment|recruit|consulting|solutions|the)\b/g, '').replace(/[^a-z0-9]/g, '');
const agency = norm(a.name);
const parts = String(a.owner_name || '').toLowerCase().replace(/[^a-z ]/g, ' ').split(/\s+/).filter(Boolean);
const firstPref = (parts[0] || '').slice(0, 3), last = parts[parts.length - 1] || '';
const nameOf = r => String(r.fullName || r.name || [r.firstName, r.lastName].filter(Boolean).join(' ') || '').toLowerCase();
const companyOf = r => norm((r.currentPosition && (r.currentPosition.companyName || r.currentPosition.company)) || (r.currentCompany && r.currentCompany.name) || r.companyName || r.headline || '');
const urlOf = r => r.linkedinUrl || r.url || r.profileUrl || '';
const titleOf = r => r.headline || (r.currentPosition && r.currentPosition.title) || r.title || '';
let best = null, bestCo = false;
for (const r of rows) {
  const nm = nameOf(r);
  const nameOk = parts.length >= 2 && nm.includes(last) && (firstPref ? nm.includes(firstPref) : true);
  if (!nameOk) continue;
  const co = companyOf(r);
  const coOk = !!(agency && co && (co.includes(agency) || agency.includes(co)));
  if (coOk) { best = r; bestCo = true; break; }
  if (!best) best = r;
}
return { json: { agency_id: a.agency_id, name: a.name, owner_name: a.owner_name, url: best ? urlOf(best) : '', title: best ? titleOf(best) : '', matched_name: best ? (best.fullName || best.name || [best.firstName, best.lastName].filter(Boolean).join(' ')) : '', company_match: bestCo, candidates: rows.length, first_candidate: rows[0] ? nameOf(rows[0]) : '' } };
